-- Ragnatale: market bot listings (Traveling Merchant). Run once in the SQL editor, after supabase/market.sql.
-- After this, a daily job (pg_cron, 00:00 UTC = 07:00 Bangkok) refreshes the bot listings by itself.
-- Bot listings have no seller account: their gold is not paid out, and unsold bot items expire without mail.
-- Re-running replaces the open bot listings that have no bids (listings with bids are kept until they end).

-- 1) Allow listings without a seller account, and mark bot listings
alter table public.auction_listings alter column seller_id drop not null;
alter table public.auction_listings add column if not exists is_bot boolean not null default false;

-- 2) Settle: skip seller mail for bot listings
create or replace function public.auction_settle() returns int
language plpgsql security definer set search_path = public as $$
declare
    l public.auction_listings;
    done int := 0;
    fee bigint;
begin
    if auth.uid() is null then raise exception 'Sign in first'; end if;
    for l in select * from public.auction_listings
             where status = 'open' and ends_at <= now()
             for update skip locked loop
        if l.top_bidder_id is not null then
            fee := floor(l.current_price * 5 / 100);
            update public.auction_listings set status = 'sold' where id = l.id;
            insert into public.mail (recipient_id, title, sender, message, rewards)
            values (l.top_bidder_id, 'Auction Won', 'Auction House',
                    'You won the auction for ' || (l.item->>'name') || '.',
                    jsonb_build_object('items', jsonb_build_array(l.item)));
            if l.seller_id is not null then
                insert into public.mail (recipient_id, title, sender, message, rewards)
                values (l.seller_id, 'Auction Sold', 'Auction House',
                        l.item->>'name' || ' sold to ' || coalesce(l.top_bidder_name, 'a buyer') || '. Sale fee ' || fee || ' gold.',
                        jsonb_build_object('gold', l.current_price - fee));
            end if;
        else
            update public.auction_listings set status = 'expired' where id = l.id;
            if l.seller_id is not null then
                insert into public.mail (recipient_id, title, sender, message, rewards)
                values (l.seller_id, 'Auction Expired', 'Auction House',
                        'No bids on ' || (l.item->>'name') || '. It is back in your mailbox.',
                        jsonb_build_object('items', jsonb_build_array(l.item)));
            end if;
        end if;
        done := done + 1;
    end loop;
    return done;
end $$;

-- 3) Stock of bot items (a pool). Each refresh picks 6 to 9 random items per category from here.
create table if not exists public.auction_bot_stock (
    id bigint generated by default as identity primary key,
    cat text not null,
    start bigint not null check (start > 0),
    item jsonb not null
);
alter table public.auction_bot_stock enable row level security;
revoke all on public.auction_bot_stock from public, anon, authenticated;

-- 4) Refresh: removes open bot listings with no bids, then lists 6 to 9 random items per category for 24 hours.
-- Bot listings that already have bids are kept until they end.
create or replace function public.market_bots_refresh() returns int
language plpgsql security definer set search_path = public as $$
declare
    cats text[] := array['weapon', 'shield', 'armor', 'hat', 'midHead', 'mouth', 'garment', 'footgear', 'ring'];
    c text;
    want int;
    r record;
    n int := 0;
begin
    delete from public.auction_listings where is_bot and status = 'open' and bid_count = 0;
    foreach c in array cats loop
        want := 6 + floor(random() * 4)::int;
        for r in select item, start from public.auction_bot_stock where cat = c order by random() limit want loop
            insert into public.auction_listings
                (seller_id, seller_name, item, category, start_price, current_price, listing_fee, duration_hours, ends_at, is_bot)
            values (null, 'Traveling Merchant', r.item, c, r.start, r.start, floor(r.start * 5 / 100), 24,
                    now() + interval '24 hours', true);
            n := n + 1;
        end loop;
    end loop;
    return n;
end $$;
revoke all on function public.market_bots_refresh() from public, anon, authenticated;

drop function if exists public.market_seed_bots(jsonb);

-- 5) Load the stock (replaces the old pool), then list the first set of bot items now
truncate public.auction_bot_stock;
insert into public.auction_bot_stock (cat, start, item)
